// src/pages/AdminDashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location
import FranchiseListAdmin from './FranchiseListAdmin';
import ExamDataCount from './count';

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Welcome to Admin Dashboard</h1>

      {/* Button Container */}
      <div style={styles.buttonContainer}>
        <button style={styles.button} onClick={() => navigate('/create-user')}>Create User</button>
        <button style={styles.button} onClick={() => navigate('/exam-data')}>Manage Exam Data</button>
        <button style={{ ...styles.button, ...styles.logout }} onClick={handleLogout}>Logout</button>
      </div>
      <ExamDataCounts/>

      {/* Franchise List */}
      <FranchiseListAdmin />
    </div>
  );
};

// CSS styles in JS format
const styles = {
  container: {
    display: 'flex',
    flexDirection: 'column',
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
  },
  header: {
    fontSize: '2rem',
    marginBottom: '20px',
    textAlign: 'center',
  },
  buttonContainer: {
    display: 'flex',
    justifyContent: 'space-between', // Ensures equal spacing between the buttons
    gap: '15px',
    marginBottom: '20px',
  },
  button: {
    padding: '12px 24px',
    fontSize: '16px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    cursor: 'pointer',
    transition: 'background-color 0.3s ease',
    width: '180px', // Ensures uniform button width
  },
  logout: {
    backgroundColor: '#dc3545',
  },
};

export default AdminDashboard;
